const express = require('express');
const crypto = require('crypto');
const sharp = require('sharp');
const Redis = require('ioredis');
const argon2 = require('argon2');

const app = express();
const redis = new Redis(process.env.REDIS_URL);

const SERVICE_REGISTRY = {
  'image-resize': { secret: process.env.RESIZE_SECRET, rateLimit: 100 },
  'image-watermark': { secret: process.env.WATERMARK_SECRET, rateLimit: 50 },
  'image-thumbnail': { secret: process.env.THUMBNAIL_SECRET, rateLimit: 200 }
};

class AuthTokenManager {
  constructor() {
    this.nonceWindow = 300000; // 5 minutes
  }

  async generateHMAC(serviceId, timestamp, nonce, payload) {
    const secret = SERVICE_REGISTRY[serviceId]?.secret;
    if (!secret) return null;
    const data = `${serviceId}:${timestamp}:${nonce}:${payload}`;
    return crypto.createHmac('sha256', secret).update(data).digest('hex');
  }

  async validateRequest(req) {
    const { serviceId, timestamp, nonce, signature } = req.headers;
    const now = Date.now();

    if (!serviceId || !timestamp || !nonce || !signature) {
      return { valid: false, reason: 'missing_headers' };
    }

    const ts = parseInt(timestamp, 10);
    if (Math.abs(now - ts) > this.nonceWindow) {
      return { valid: false, reason: 'expired_timestamp' };
    }

    const nonceKey = `nonce:${serviceId}:${nonce}`;
    const nonceUsed = await redis.get(nonceKey);
    if (nonceUsed) {
      return { valid: false, reason: 'replay_detected' };
    }

    const payloadHash = crypto.createHash('sha256')
      .update(JSON.stringify(req.body || ''))
      .digest('hex');

    const expectedSig = await this.generateHMAC(serviceId, timestamp, nonce, payloadHash);
    if (!expectedSig) {
      return { valid: false, reason: 'unknown_service' };
    }

    const isValid = this.timingSafeCompare(signature, expectedSig);

    if (isValid) {
      await redis.setex(nonceKey, 600, '1');
    }

    return { valid: isValid, serviceId, reason: isValid ? 'ok' : 'invalid_signature' };
  }

  timingSafeCompare(a, b) {
    if (typeof a !== 'string' || typeof b !== 'string') return false;
    const bufA = Buffer.from(a, 'utf8');
    const bufB = Buffer.from(b, 'utf8');
    if (bufA.length !== bufB.length) return false;
    return crypto.timingSafeEqual(bufA, bufB);
  }
}

class RateLimiter {
  async checkLimit(serviceId, clientIp) {
    const config = SERVICE_REGISTRY[serviceId];
    if (!config) return false;

    const windowKey = `ratelimit:${serviceId}:${clientIp}:${Math.floor(Date.now() / 60000)}`;
    const current = await redis.incr(windowKey);
    if (current === 1) {
      await redis.expire(windowKey, 120);
    }
    return current <= config.rateLimit;
  }

  async recordFailedAuth(serviceId, clientIp) {
    const failKey = `authfail:${serviceId}:${clientIp}`;
    const failures = await redis.incr(failKey);
    if (failures === 1) {
      await redis.expire(failKey, 900);
    }
    return failures;
  }

  async isBlocked(serviceId, clientIp) {
    const failKey = `authfail:${serviceId}:${clientIp}`;
    const failures = parseInt(await redis.get(failKey) || '0', 10);
    return failures >= 10;
  }
}

const authManager = new AuthTokenManager();
const rateLimiter = new RateLimiter();

async function authMiddleware(req, res, next) {
  const clientIp = req.ip;
  const serviceId = req.headers['serviceid'];

  if (await rateLimiter.isBlocked(serviceId, clientIp)) {
    return res.status(429).json({ error: 'too_many_failures' });
  }

  const result = await authManager.validateRequest(req);

  if (!result.valid) {
    if (result.reason === 'invalid_signature' || result.reason === 'unknown_service') {
      await rateLimiter.recordFailedAuth(serviceId, clientIp);
    }
    return res.status(401).json({ error: result.reason });
  }

  if (!(await rateLimiter.checkLimit(serviceId, clientIp))) {
    return res.status(429).json({ error: 'rate_limited' });
  }

  req.authenticatedService = result.serviceId;
  next();
}

app.post('/api/process', express.json({ limit: '10mb' }), authMiddleware, async (req, res) => {
  try {
    const { operation, imageData, options } = req.body;
    const buffer = Buffer.from(imageData, 'base64');

    let result;
    switch (operation) {
      case 'resize':
        result = await sharp(buffer).resize(options.width, options.height).toBuffer();
        break;
      case 'watermark':
        result = await sharp(buffer).composite([{ input: Buffer.from(options.overlay, 'base64') }]).toBuffer();
        break;
      case 'thumbnail':
        result = await sharp(buffer).resize(150, 150, { fit: 'cover' }).toBuffer();
        break;
      default:
        return res.status(400).json({ error: 'unknown_operation' });
    }

    res.json({ result: result.toString('base64') });
  } catch (err) {
    res.status(500).json({ error: 'processing_failed' });
  }
});

app.listen(3000);
module.exports = app;
